"""Untimed complete public current-ink plans against the published 838 graph.

Only DrawBot, PixelData and SketchFillRenderer vary between sides. All other
dependencies come from the same recorded current checkout. No drawing/input,
network operation, timing or allocation probe is performed.
"""
import argparse
from contextlib import ExitStack, closing, contextmanager
from dataclasses import fields, is_dataclass
import hashlib
import importlib
import json
from pathlib import Path
import platform
import subprocess
import sys
import types
from unittest.mock import patch


BASELINE = '8e0a0e4c61ca0742dfb7857649103477cd307516'
GRAPH_NAMES = ('PixelData', 'SketchFillRenderer', 'DrawBot')
IMPORT_ALIASES = (('AutoSketchBudget', 'monochrome_strokes', 'PixelData', 'monochrome_strokes'),
                  ('FillOptimizer', 'closest_color', 'PixelData', 'closest_color'))


def sha256(raw):
    return hashlib.sha256(raw).hexdigest()


def digest(value):
    return sha256(json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False).encode())


def source_hashes(root):
    return {path.name: sha256(path.read_bytes()) for path in sorted(root.glob('*.py'))}


def raw_hashes(root):
    return {str(path.relative_to(root)): sha256(path.read_bytes())
            for path in sorted((root / 'docs').glob('*benchmark*.json'))}


@contextmanager
def linked_graph(graph, *, aliases=True):
    previous = {name: sys.modules.get(name) for name in graph}
    sys.modules.update(graph)
    try:
        with ExitStack() as stack:
            if aliases:
                for target, attribute, source, original in IMPORT_ALIASES:
                    stack.enter_context(patch.object(sys.modules[target], attribute, getattr(graph[source], original)))
            yield
    finally:
        for name, module in previous.items():
            if module is None:
                sys.modules.pop(name, None)
            else:
                sys.modules[name] = module


def historical_graph(root, revision):
    # Initialize every shared dependency through the complete current graph
    # before introducing any partially populated historical module objects.
    current = {name: importlib.import_module(name) for name in GRAPH_NAMES}
    for target, _attribute, _source, _original in IMPORT_ALIASES:
        importlib.import_module(target)
    sources = {name: subprocess.check_output(['git', 'show', f'{revision}:{name}.py'], cwd=root)
               for name in GRAPH_NAMES}
    before = {}
    for name in GRAPH_NAMES:
        alias = f'_current_ink_history_{revision[:12]}_{name}'
        module = types.ModuleType(alias)
        module.__file__ = str(root / (name + '.py'))
        module.__package__ = ''
        sys.modules[alias] = module  # dataclass type resolution, without plan data
        before[name] = module
    with linked_graph(before, aliases=False):
        for name in GRAPH_NAMES:
            exec(compile(sources[name], before[name].__file__, 'exec'), before[name].__dict__)
    return before, current, {name: sha256(raw) for name, raw in sources.items()}


def first_difference(before, after, path=()):
    if isinstance(before, dict) and isinstance(after, dict):
        if before.keys() != after.keys():
            return f'{path}: keys differ {before.keys() ^ after.keys()}'
        for key in before:
            if before[key] != after[key]:
                return first_difference(before[key], after[key], (*path, key))
    if isinstance(before, list) and isinstance(after, list):
        if len(before) != len(after):
            return f'{path}: lengths {len(before)} != {len(after)}'
        for index, (left, right) in enumerate(zip(before, after)):
            if left != right:
                return first_difference(left, right, (*path, index))
    return f'{path}: {before!r} != {after!r}'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path,
                        default=Path(__file__).resolve().parent / 'Image-Draw-Bot-batch27')
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--baseline', default=BASELINE)
    args = parser.parse_args()
    root = args.root.resolve()
    if args.output.exists():
        parser.error('Choose a new report path; historical reports are never overwritten.')
    sys.path.insert(0, str(root))
    import numpy as np
    from PIL import Image, __version__ as pillow_version
    import ResourceAllocation
    import test_v148_rendering_batch27_monochrome_ownership as fixture
    from test_precision_v102 import Value
    from test_v148_rendering_batch15_sketch_memory import VOLATILE_PATHS
    from test_v148_rendering_batch17_layered_diagnostics import calibrated

    def comparable(value, path=()):
        if isinstance(value, Image.Image):
            result = dict(mode=value.mode, size=list(value.size), sha256=sha256(value.tobytes()),
                          info=comparable(dict(value.info), (*path, 'image_info')))
            if value.palette is not None:
                result['palette'] = dict(mode=value.palette.mode, sha256=sha256(value.palette.tobytes()))
            return {'image': result}
        if isinstance(value, np.ndarray):
            return {'array': dict(shape=list(value.shape), dtype=str(value.dtype), sha256=sha256(value.tobytes()))}
        if isinstance(value, np.generic):
            return value.item()
        if isinstance(value, bytes):
            return {'bytes': dict(length=len(value), sha256=sha256(value))}
        if is_dataclass(value) and not isinstance(value, type):
            return {field.name: comparable(getattr(value, field.name), (*path, field.name))
                    for field in fields(value)}
        if isinstance(value, dict):
            return {key: comparable(item, (*path, key)) for key, item in value.items()
                    if (*path, key) not in VOLATILE_PATHS}
        if isinstance(value, (tuple, list)):
            result = [comparable(item, path) for item in value]
            attributes = getattr(value, '__dict__', None)
            if attributes:
                return {'sequence': result, 'attributes': comparable(attributes, (*path, '__attributes__'))}
            return result
        if value is None or isinstance(value, (str, int, float, bool)):
            return value
        raise TypeError(f'Uncompared field at {path}: {type(value).__name__}')

    def close_plan(value, source, seen=None):
        seen = set() if seen is None else seen
        if id(value) in seen:
            return
        seen.add(id(value))
        if isinstance(value, Image.Image):
            if value is not source:
                value.close()
        elif isinstance(value, dict):
            for item in value.values():
                close_plan(item, source, seen)
        elif isinstance(value, (tuple, list)):
            for item in value:
                close_plan(item, source, seen)

    sources_before = source_hashes(root)
    originals_before = raw_hashes(root)
    before, after, old_hashes = historical_graph(root, args.baseline)
    # Capture actual OS observations once, then supply this same observation to
    # both real allocation/options paths. Resource policy itself is not mocked.
    current_cpus = ResourceAllocation.logical_cpu_count()
    current_ram = ResourceAllocation.available_ram_mb()
    report = dict(schema=1, baseline=args.baseline, verify_only=True, repeats=0,
        method='Eight untimed full public current-ink/explicit-Balanced-sketch pairs; no elapsed or allocation probes.',
        scope='Complete published DrawBot, PixelData and SketchFillRenderer versus current counterparts; '
              'all other dependencies use the identical recorded current checkout. This is an isolated '
              'compatibility comparison, not a reconstruction of the entire historical application.',
        python=sys.version.split()[0], platform=platform.platform(), numpy=np.__version__, pillow=pillow_version,
        script_sha256=sha256(Path(__file__).read_bytes()),
        historical_module_sha256=old_hashes,
        linked_shared_aliases=[dict(target=target + '.' + attribute, source=source + '.' + original)
                              for target, attribute, source, original in IMPORT_ALIASES],
        current_module_sha256={name: sources_before[name + '.py'] for name in GRAPH_NAMES},
        source_hashes_before=sources_before, historical_raw_sha256_before=originals_before,
        comparison_exclusions=[list(path) for path in sorted(VOLATILE_PATHS)],
        control_inputs=dict(logical_cpus=current_cpus, available_ram_mb=current_ram,
            sketch_detail='Balanced',
            detail_scope='Actual explicit UI selection; Auto-detail sampling and live timer/rescue behavior are outside this comparison.',
            cost_context='One private real calibration fixture; load_profile=None in the existing fixture; '
                         'explicit identical empty execution-cost calibration override for both sides.'),
        cases=[])
    with calibrated(), ExitStack() as stack:
        real_app = fixture.renderer_fixture.AdvertisedRendererTests.app
        def explicit_sketch_app(testcase, *arguments, **keywords):
            app = real_app(testcase, *arguments, **keywords)
            app.sketch_detail = Value('Balanced')
            return app
        stack.enter_context(patch.object(fixture.renderer_fixture.AdvertisedRendererTests,
                                        'app', explicit_sketch_app))
        stack.enter_context(patch.object(ResourceAllocation, 'logical_cpu_count', return_value=current_cpus))
        stack.enter_context(patch.object(ResourceAllocation, 'available_ram_mb', return_value=current_ram))
        for graph in (before, after):
            stack.enter_context(patch.object(graph['DrawBot'], 'custom_rgb_available', return_value=False))
            stack.enter_context(patch.object(graph['DrawBot'], 'log_event'))
        for mode in ('RGB', 'RGBA', 'L', 'P'):
            for outline in (False, True):
                with closing(fixture.source_image(mode)) as source:
                    source_before = comparable(source)
                    outputs, settings = [], []
                    for graph in (before, after):
                        plan = None
                        try:
                            with linked_graph(graph), patch.object(fixture, 'DrawBot', graph['DrawBot']):
                                options = fixture.public_options(outline=outline)
                                if not options['paint_current_color'] or options['outline'] is not outline:
                                    raise AssertionError('Actual UI options did not select the requested current-ink route.')
                                if options['sketch_detail'] != 'Balanced':
                                    raise AssertionError('Actual UI options did not preserve explicit Balanced sketch detail.')
                                options['_execution_cost_calibration_override'] = {}
                                settings.append(comparable(options))
                                plan = graph['DrawBot'].make_plan(source, source.size, options)
                                if plan['count'] <= 0 or plan['colors'] != ((0, 0, 0),):
                                    raise AssertionError('The actual public result is not the expected nonempty current-ink plan.')
                                outputs.append(comparable(plan))
                        finally:
                            close_plan(plan, source)
                        if comparable(source) != source_before:
                            raise AssertionError('The public planner changed or closed its caller-owned source.')
                    case = dict(source_mode=mode, outline=outline, source=source_before,
                        source_unchanged=True, options_equal=settings[0] == settings[1],
                        full_plan_equal=outputs[0] == outputs[1],
                        before_options=settings[0], after_options=settings[1],
                        before_plan=outputs[0], after_plan=outputs[1],
                        before_plan_sha256=digest(outputs[0]), after_plan_sha256=digest(outputs[1]))
                    if not case['options_equal']:
                        case['options_difference'] = first_difference(*settings)
                    if not case['full_plan_equal']:
                        case['plan_difference'] = first_difference(*outputs)
                    report['cases'].append(case)
    report['source_hashes_after'] = source_hashes(root)
    report['historical_raw_sha256_after'] = raw_hashes(root)
    report['sources_unchanged'] = sources_before == report['source_hashes_after']
    report['historical_raw_unchanged'] = originals_before == report['historical_raw_sha256_after']
    report['source_manifest_sha256'] = digest(sources_before)
    report['pair_count'] = len(report['cases'])
    report['all_pairs_equal'] = all(row['options_equal'] and row['full_plan_equal'] for row in report['cases'])
    report['passed'] = report['pair_count'] == 8 and report['all_pairs_equal'] and report['sources_unchanged'] and report['historical_raw_unchanged']
    args.output.parent.mkdir(parents=True, exist_ok=True)
    with args.output.open('x', encoding='utf-8') as stream:
        json.dump(report, stream, ensure_ascii=False, indent=2, allow_nan=False)
        stream.write('\n')
    print(json.dumps(dict(output=str(args.output), sha256=sha256(args.output.read_bytes()),
        pairs=report['pair_count'], passed=report['passed'], sources_unchanged=report['sources_unchanged'],
        historical_raw_unchanged=report['historical_raw_unchanged'],
        differences=[{key: row[key] for key in ('source_mode', 'outline', 'options_difference', 'plan_difference') if key in row}
                     for row in report['cases'] if not row['options_equal'] or not row['full_plan_equal']]), ensure_ascii=False))
    return 0 if report['passed'] else 1


if __name__ == '__main__':
    raise SystemExit(main())
